import numpy as np

def R(x, y, z):
    numerator = (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1)
    denominator = x*y + y*z + z*x
    if denominator == 0:
        return float('inf')
    return numerator / denominator

# Test a grid of values around (0.5, 0.5, 0.5)
# We test x, y, z from 0.2 to 0.8 with step 0.1
steps = np.arange(0.2, 0.9, 0.1)
results = []
target_R = 4.5

print(f"Searching for R < {target_R} when x, y, z are unequal.")

for x in steps:
    for y in steps:
        for z in steps:
            if abs(x - y) > 1e-6 or abs(y - z) > 1e-6 or abs(x - z) > 1e-6:
                r_val = R(x, y, z)
                if r_val < target_R:
                    print(f"Counterexample found: x={x}, y={y}, z={z}, R={r_val}")

                # If we found a value close to 9/2, we might log it
                # elif r_val < 5.0:
